        "comm-ethiopian",
        "Tewahedo — Athanasius of Alexandria",
        "Athanasius of Alexandria (350).",
        '<aside class="note-comm-ethiopian"><strong>Athanasius of Alexandria</strong> <em>Orationes contra Arianos II.81</em> <small>(c. 350 AD)</small><p>&#x27;Then I was by him, as one brought up with him&#x27; (LXX 8:30 — ēmēn par&#x27; autō harmozousa) — Athanasius marks harmozousa (a harmoniser/fitter-together; cf. some MSS architechtonousa, a master-architect/master-builder) as the WISDOM-AS-CO-CREATIONAL-AGENT anchor: Wisdom is not the Father&#x27;s-instrument-from-outside but intra-divine co-architect, harmonising-all-things from within the divine-counsel. The text par&#x27; autō (BY him, beside him) positions Wisdom as eternal-companion-of-the-Father, not posterior-creature. Pairs with Jn 1:3 (panta di&#x27; autou egeneto — &#x27;all things were made through him&#x27;) as the canonical Wisdom-as-Trinitarian-creator pair.</p></aside>',
        "Athanasius of Alexandria, Orationes contra Arianos (Four Discourses Against the Arians, I-IV), in Select Writings and Letters of Athanasius, Nicene and Post-Nicene Fathers (NPNF), Series 2, Vol. 4, ed. Archibald Robertson (Oxford / T&T Clark, 1892). PD. Greek text in Migne PG 26 (1857).",
